-- Calibrate untouched starter styles only. Preserve administrator edits and publication decisions.
UPDATE creation_styles AS s SET name=v.name,text=v.text,revision=s.revision+1,updated_at=now()
FROM (VALUES
 ('00000000-0000-4000-8000-000000000001'::uuid,'真实摄影','真实摄影，自然光线，细腻材质，准确的光影与丰富细节。','真实摄影','采用真实摄影的表现方式，自然可信的光线、材质与空间透视，色彩克制。主体、场景和构图遵循创作需求，不额外添加景物或装饰。'),
 ('00000000-0000-4000-8000-000000000002'::uuid,'商业产品','高端商业产品摄影，精致棚拍布光，主体清晰，构图简洁。','商品棚拍','采用商品棚拍的表现方式，柔和可控的布光，清楚呈现商品轮廓、材质与细节，背景简洁、不抢主体。使用参考商品时保留其外形、配色与标识，不虚构功能或添加宣传文字。'),
 ('00000000-0000-4000-8000-000000000003'::uuid,'精致插画','专业编辑插画，清晰造型，丰富而协调的配色，精致完成度。','平面插画','采用平面插画的表现方式，以清晰轮廓、概括造型和协调色块表达主体，减少写实纹理，保持画面易读。人物、物品与场景按创作需求呈现，不额外添加文字或装饰元素。'),
 ('00000000-0000-4000-8000-000000000004'::uuid,'海报视觉','鲜明的海报构图，突出视觉焦点，预留排版空间，电影感配色。','海报视觉','采用海报式视觉组织，明确主次与视觉焦点，运用有控制的色彩对比和疏密关系。是否留白、文字内容及其位置遵循创作需求，不自行编造标题、口号或标志。'),
 ('00000000-0000-4000-8000-000000000005'::uuid,'头像角色','富有表现力的角色肖像，突出面部表情，干净背景，精致头像质感。','简洁 3D','采用简洁的三维渲染表现，体块清楚，材质统一，柔和布光与自然接触阴影，背景简洁。保留创作需求中的主体特征与结构，不默认将主体拟人化，也不额外添加文字或配件。')
) AS v(id,old_name,old_text,name,text)
WHERE s.id=v.id AND s.workspace_id IS NULL AND s.name=v.old_name AND s.text=v.old_text
 AND s.revision=1 AND s.published AND NOT s.deleted;
